#include <bits/stdc++.h>
using namespace std;struct C{int s,l,m,ex,lm,in,out,g,type;};struct R{double w,dd;int orders;};
R run(vector<int>const&p,C c){int cash=10000,sh=0,pend=0,peak=10000,orders=0,tr=0,mr=0,want=0;long long ss=0,sl=0,sm=0;double dd=0;for(int i=0;i<p.size();i++){int x=p[i],n=0;if(pend==1){n=min(63,max(0,(cash-5)/x));if(n){cash-=n*x+5;sh+=n;orders++;}}else if(pend==2){n=min(63,sh);if(n&&cash+n*x>=5){cash+=n*x-5;sh-=n;orders++;}}int w=cash+sh*x;peak=max(peak,w);dd=max(dd,double(peak-w)/peak);ss+=x-(i>=c.s?p[i-c.s]:0);sl+=x-(i>=c.l?p[i-c.l]:0);sm+=x-(i>=c.lm?p[i-c.lm]:0);if(i+1>=max(c.l,c.lm)){long long D=c.s*c.l,d=ss*c.l-sl*c.s;int dm=x*c.lm-sm;if(d>c.m*D)tr=1;else if(d<-c.ex*D)tr=0;if(dm<-c.in*c.lm)mr=1;else if(dm>c.out*c.lm)mr=0;switch(c.type){case 0:want=tr||(mr&&d>=-c.g*D);break;case 1:want=tr||(mr&&d>=c.g*D);break;case 2:want=tr&&dm<=c.out*c.lm;break;case 3:want=tr;break;case 4:want=mr&&d>=-c.g*D;break;case 5:if((tr||mr)&&d>=-c.g*D)want=1;else if(d<-c.g*D||dm>c.out*c.lm)want=0;break;}}pend=want?1:2;}return{double(cash+sh*p.back()),dd,orders};}
vector<int>read(string f){ifstream in(f);string s;getline(in,s);vector<int>p;while(getline(in,s))if(s.size())p.push_back(stoi(s.substr(s.find(',')+1)));return p;}
int main(){auto a=read("tb/practica.csv"),b=read("tb/practica_meta.csv");vector<vector<int>> tr;for(auto p:{a,b})for(int i=0;i<12000;i+=3000)tr.emplace_back(p.begin()+i,p.begin()+i+3000);vector<C> cs;cs.push_back({20,120,8,8,60,4,0,4,0});mt19937 rng(42);int S[]={8,16,20,32,64,128},L[]={64,120,128,192,256,384,512,768,1024},M[]={0,1,2,3,4,6,8},LM[]={16,32,48,60,64,96,128,192},IN[]={2,3,4,5,6},OUT[]={0,1,2},G[]={0,1,2,4,6,8};for(int i=0;i<22000;i++){C c{S[rng()%6],L[rng()%9],M[rng()%7],M[rng()%7],LM[rng()%8],IN[rng()%5],OUT[rng()%3],G[rng()%6],int(rng()%6)};if(c.s<c.l&&c.lm<=c.l)cs.push_back(c);}vector<pair<double,int>> rs;for(int k=0;k<cs.size();k++){double s[2]={};for(int i=0;i<8;i++){auto r=run(tr[i],cs[k]);s[i/4]+=(log(max(1.,r.w)/10000.)-.5*r.dd)/4;}rs.push_back({(s[0]+s[1])/2-.6*abs(s[0]-s[1]),k});}sort(rs.rbegin(),rs.rend());auto show=[&](C c,double sc){cout<<sc<<" "<<c.s<<" "<<c.l<<" "<<c.m<<" "<<c.ex<<" "<<c.lm<<" "<<c.in<<" "<<c.out<<" "<<c.g<<" "<<c.type;for(auto p:{a,b}){auto r=run(p,c);vector<int>h(p.begin()+12000,p.end());auto t=run(h,c);cout<<" full "<<r.w<<" "<<r.dd<<" test "<<t.w<<" "<<t.dd;}cout<<"\n";};show(cs[0],0);for(int i=0;i<25;i++)show(cs[rs[i].second],rs[i].first);}
